#include <stdio.h>

int main(void) {
    printf("=== integer promotion and usual arithmetic conversions ===\n");

    printf("\n[1] signed meets unsigned\n");
    printf("    (int)-1 > (unsigned)1        -> %s\n", (-1 > 1u) ? "TRUE (!)" : "false");
    printf("    (unsigned)-1                 = %u\n", (unsigned)-1);
    printf("    reason: -1 is converted to UINT_MAX before the comparison\n");

    printf("\n[2] char signedness is implementation-defined\n");
    char c = (char)200;
    printf("    (char)200        = %d\n", (int)c);
    printf("    (signed char)200 = %d\n", (int)(signed char)200);
    printf("    (unsigned char)200 = %u\n", (unsigned)(unsigned char)200);

    printf("\n[3] short is promoted to int BEFORE the arithmetic\n");
    short a = 30000, b = 30000;
    printf("    (short)30000 + (short)30000 = %d   (int math, no overflow here)\n", a + b);
    printf("    cast back to short          = %d   (60000 - 65536)\n", (int)(short)(a + b));

    printf("\n[4] sizeof and unsigned underflow\n");
    printf("    sizeof(int)=%d sizeof(1)=%d sizeof(1u)=%d\n",
           (int)sizeof(int), (int)sizeof(1), (int)sizeof(1u));
    printf("    (unsigned)0 - 1u = %u   (wraps, never -1)\n", (unsigned)0 - 1u);

    printf("\n[5] shifting\n");
    printf("    1u << 31 = %u = 0x%08X\n", 1u << 31, 1u << 31);
    printf("    1  << 31 would be UB (signed overflow)\n");

    printf("\n[6] integer division truncates toward zero\n");
    printf("    -7 / 2 = %d    -7 %% 2 = %d\n", -7 / 2, -7 % 2);
    printf("    7 / -2 = %d     7 %% -2 = %d   (remainder takes the dividend's sign)\n", 7 / -2, 7 % -2);
    return 0;
}
